-- STEP12: enforce existing cashier desk scope on legacy receipt, invoice, stage, addition and change RPCs, and item-note reader.
CREATE OR REPLACE FUNCTION public.ff38_cashier_invoice_addition(p_addition uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
    DECLARE
        v_user uuid;
            v_role text;
                v_order uuid;
                    v_branch uuid;
                        v_status text;
                            v_phase text;
                                v_amount numeric;
                                    v_count integer;
                                    BEGIN
                                        v_user := auth.uid();

                                            IF v_user IS NULL THEN
                                                    RAISE EXCEPTION 'يجب تسجيل الدخول أولاً';
                                                        END IF;

                                                            SELECT role
                                                                INTO v_role
                                                                    FROM public.ff_profiles
                                                                        WHERE user_id = v_user
                                                                              AND active = true;

                                                                                  IF v_role IS NULL
                                                                                         OR v_role NOT IN ('manager', 'cashier') THEN
                                                                                                 RAISE EXCEPTION 'هذه العملية للكاشير أو المدير فقط';
                                                                                                     END IF;

                                                                                                         SELECT a.order_id, a.status, a.amount
                                                                                                             INTO v_order, v_status, v_amount
                                                                                                                 FROM public.ff38_order_additions a
                                                                                                                     WHERE a.id = p_addition
                                                                                                                         FOR UPDATE;

                                                                                                                             IF NOT FOUND THEN
                                                                                                                                     RAISE EXCEPTION 'الإضافة غير موجودة';
                                                                                                                                         END IF;

                                                                                                                                             IF v_status <> 'pending' THEN
                                                                                                                                                     RAISE EXCEPTION 'الإضافة ليست بانتظار الفاتورة';
                                                                                                                                                         END IF;

                                                                                                                                                             SELECT branch_id
                                                                                                                                                                 INTO v_branch
                                                                                                                                                                     FROM public.ff_orders
                                                                                                                                                                         WHERE id = v_order
                                                                                                                                                                             FOR UPDATE;

                                                                                                                                                                                 IF NOT FOUND THEN
                                                                                                                                                                                         RAISE EXCEPTION 'الطلب الأصلي غير موجود';
                                                                                                                                                                                             END IF;

                                                                                                                                                                                                 IF v_role <> 'manager'
                                                                                                                                                                                                        AND NOT EXISTS (
                                                                                                                                                                                                                   SELECT 1
                                                                                                                                                                                                                              FROM public.ff_user_branches
                                                                                                                                                                                                                                         WHERE user_id = v_user
                                                                                                                                                                                                                                                      AND branch_id = v_branch
                                                                                                                                                                                                                                                             )
                                                                                                                                                                                                                                                                 THEN
                                                                                                                                                                                                                                                                         RAISE EXCEPTION 'ليس لديك صلاحية لهذا الفرع';
                                                                                                                                                                                                                                                                             END IF;

                                                                                                                                                                                                                                                                                 IF NOT public.ff_is_manager() AND NOT ff_private.a05_can_read_order(v_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 SELECT phase INTO v_phase
                                                                                                                                                                                                                                                                                         FROM public.ff38_delivery_tasks
                                                                                                                                                                                                                                                                                             WHERE order_id = v_order
                                                                                                                                                                                                                                                                                                 FOR UPDATE;

                                                                                                                                                                                                                                                                                                     IF v_phase IS DISTINCT FROM 'assigned' THEN
                                                                                                                                                                                                                                                                                                             RAISE EXCEPTION 'لا يمكن اعتماد الإضافة بعد خروج الموصل';
                                                                                                                                                                                                                                                                                                                 END IF;

                                                                                                                                                                                                                                                                                                                     SELECT count(*)
                                                                                                                                                                                                                                                                                                                         INTO v_count
                                                                                                                                                                                                                                                                                                                             FROM public.ff38_order_addition_items
                                                                                                                                                                                                                                                                                                                                 WHERE addition_id = p_addition;

                                                                                                                                                                                                                                                                                                                                     IF v_count = 0 THEN
                                                                                                                                                                                                                                                                                                                                             RAISE EXCEPTION 'لا توجد أصناف في الإضافة';
                                                                                                                                                                                                                                                                                                                                                 END IF;

                                                                                                                                                                                                                                                                                                                                                     UPDATE public.ff38_order_additions
                                                                                                                                                                                                                                                                                                                                                         SET status = 'invoiced',
                                                                                                                                                                                                                                                                                                                                                                 invoiced_by = v_user,
                                                                                                                                                                                                                                                                                                                                                                         invoiced_at = now()
                                                                                                                                                                                                                                                                                                                                                                             WHERE id = p_addition;

                                                                                                                                                                                                                                                                                                                                                                                 RETURN jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                         'success', true,
                                                                                                                                                                                                                                                                                                                                                                                                 'addition_id', p_addition,
                                                                                                                                                                                                                                                                                                                                                                                                         'order_id', v_order,
                                                                                                                                                                                                                                                                                                                                                                                                                 'status', 'invoiced',
                                                                                                                                                                                                                                                                                                                                                                                                                         'amount', v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                 'items_count', v_count
                                                                                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                                                                                     END;
                                                                                                                                                                                                                                                                                                                                                                                                                                     $function$;

CREATE OR REPLACE FUNCTION public.ff38_cashier_set_stage(p_order uuid, p_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text;v_branch uuid;v_existing text;v_old_index int;v_new_index int;v_status text;v_delivered_at timestamptz;
begin
 select role into v_role from public.ff_profiles where user_id=auth.uid() and active;
 if v_role not in ('manager','cashier') or v_role is null then raise exception 'للكاشير فقط' using errcode='42501';end if;
 
  PERFORM 1 FROM public.ff_orders WHERE id=p_order FOR UPDATE;
  select o.branch_id,t.cashier_stage,o.status,t.delivered_at into v_branch,v_existing,v_status,v_delivered_at
 from public.ff38_delivery_tasks t join public.ff_orders o on o.id=t.order_id
 where t.order_id=p_order for update of t;
 if not found then raise exception 'الطلب غير مسند لموصل بعد';end if;
 if v_status in ('cancelled','delivered') or v_delivered_at is not null then
  raise exception 'الطلب ملغي أو منتهٍ؛ لا يمكن تغيير حالة الكاشير';
 end if;
 if v_role='cashier' and not exists(select 1 from public.ff_user_branches where user_id=auth.uid() and branch_id=v_branch)
 then raise exception 'فرع غير مصرح' using errcode='42501';end if;
 IF NOT public.ff_is_manager() AND NOT ff_private.a05_can_read_order(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 v_old_index=array_position(array['waiting','printed','preparing','ready','handed_over'],v_existing);
 v_new_index=array_position(array['waiting','printed','preparing','ready','handed_over'],p_stage);
 if v_new_index is null or v_new_index<>v_old_index+1 then raise exception 'يجب تحديث مراحل الكاشير بالترتيب';end if;
 update public.ff38_delivery_tasks set cashier_stage=p_stage,updated_at=now() where order_id=p_order;
 return jsonb_build_object('stage',p_stage,'order_id',p_order);
end;$function$;

CREATE OR REPLACE FUNCTION public.ff49_cashier_invoice(p_order uuid, p_invoice_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   DECLARE v_branch uuid;v_stage text;v_result jsonb;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  PERFORM 1 FROM public.ff_orders WHERE id=p_order FOR UPDATE;
  SELECT o.branch_id,t.cashier_stage INTO v_branch,v_stage
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             WHERE o.id=p_order FOR UPDATE OF t;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  IF NOT FOUND OR NOT public.ff49_can_work_branch(v_branch,ARRAY['manager','cashier']) THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
   IF NOT public.ff_is_manager() AND NOT ff_private.a05_can_read_order(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
       WHERE o.id=p_order AND (o.order_type<>'delivery' OR o.status IN ('cancelled','delivered','reservation_completed') OR t.delivered_at IS NOT NULL))
   THEN RAISE EXCEPTION 'الطلب ملغي أو منتهٍ؛ لا يمكن استلامه أو اعتماد فاتورته'; END IF;
   IF v_stage<>'waiting' OR length(btrim(coalesce(p_invoice_ref,''))) > 80 THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           RAISE EXCEPTION 'لا يمكن اعتماد القطع في هذه المرحلة أو أن رقم الفاتورة أطول من 80 حرفًا'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      IF NOT EXISTS (SELECT 1 FROM public.ff49_cashier_receipts WHERE order_id=p_order) THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   RAISE EXCEPTION 'أكد استلام الطلب أولًا'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 -- Validated prior to stage transition, then stored in same transaction.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                UPDATE public.ff49_cashier_receipts SET invoice_ref=nullif(btrim(p_invoice_ref),''),invoiced_by=auth.uid(),invoiced_at=now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WHERE order_id=p_order AND invoiced_at IS NULL;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 IF NOT FOUND THEN RAISE EXCEPTION 'سبق ربط الفاتورة بهذا الطلب'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   v_result:=public.ff38_cashier_set_stage(p_order,'printed');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      RETURN v_result||jsonb_build_object('external_invoice_ref',nullif(btrim(p_invoice_ref),''));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         END; $function$;

CREATE OR REPLACE FUNCTION public.ff49_cashier_receive(p_order uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                       DECLARE v_branch uuid; v_stage text;
                                       BEGIN
                                        
  PERFORM 1 FROM public.ff_orders WHERE id=p_order FOR UPDATE;
  SELECT o.branch_id,t.cashier_stage INTO v_branch,v_stage
                                         FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
                                          WHERE o.id=p_order FOR UPDATE OF t;
                                           IF NOT FOUND OR NOT public.ff49_can_work_branch(v_branch,ARRAY['manager','cashier']) THEN
                                             RAISE EXCEPTION 'للكاشير المصرح بهذا الفرع فقط' USING ERRCODE='42501'; END IF;
                                              
   IF NOT public.ff_is_manager() AND NOT ff_private.a05_can_read_order(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
       WHERE o.id=p_order AND (o.order_type<>'delivery' OR o.status IN ('cancelled','delivered','reservation_completed') OR t.delivered_at IS NOT NULL))
   THEN RAISE EXCEPTION 'الطلب ملغي أو منتهٍ؛ لا يمكن استلامه أو اعتماد فاتورته'; END IF;
   IF v_stage<>'waiting' THEN RAISE EXCEPTION 'لا يمكن استلام الطلب بهذه الحالة'; END IF;
                                               INSERT INTO public.ff49_cashier_receipts(order_id,received_by)
                                                VALUES(p_order,auth.uid()) ON CONFLICT(order_id) DO NOTHING;
                                                 RETURN jsonb_build_object('received',true,'order_id',p_order);
                                                 END $function$;

CREATE OR REPLACE FUNCTION public.ff50_change_cashier_confirm_pos(p_change uuid, p_invoice_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      DECLARE v public.ff50_order_changes%ROWTYPE;v_branch uuid;v_phase text;v_stage text;v_status text;v_total numeric;v_current_items jsonb;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             IF length(btrim(coalesce(p_invoice_ref,''))) > 80 THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   RAISE EXCEPTION 'مرجع الفاتورة الاختياري لا يمكن أن يتجاوز 80 حرفًا'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          SELECT * INTO v FROM public.ff50_order_changes WHERE id=p_change FOR UPDATE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  IF NOT FOUND OR v.status<>'service_confirmed' THEN RAISE EXCEPTION 'التعديل غير معتمد من الخدمة والكاشير'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           SELECT o.branch_id,t.phase,t.cashier_stage,o.status INTO v_branch,v_phase,v_stage,v_status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WHERE o.id=v.order_id FOR UPDATE OF o,t;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            IF NOT public.ff49_can_work_branch(v_branch,ARRAY['manager','cashier']) THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         IF NOT public.ff_is_manager() AND NOT ff_private.a05_can_read_order(v.order_id) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 IF v_phase IS DISTINCT FROM 'assigned' OR v_stage='handed_over' OR v_status IN ('cancelled','canceled','delivered','closed','reservation_completed') THEN RAISE EXCEPTION 'لا تعديل بعد خروج الموصل'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         IF EXISTS (SELECT 1 FROM public.ff38_order_additions WHERE order_id=v.order_id AND status='pending') THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           RAISE EXCEPTION 'أنهِ الإضافة المعلقة أولًا'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -- Existing values were captured at proposal time; detect intervening edits.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v.old_items) e WHERE NOT (e ? 'item_notes')) THEN
  -- Preserve older proposal format. Refuse any old proposal that could erase notes.
  IF EXISTS(SELECT 1 FROM public.ff_order_items WHERE order_id=v.order_id AND item_notes<>'') THEN
   RAISE EXCEPTION 'طلب تعديل قديم لا يتضمن الملاحظات؛ راجع الطلب قبل التعديل';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',item_name,'qty',quantity,'price',unit_price) ORDER BY item_name),'[]'::jsonb)
   INTO v_current_items FROM public.ff_order_items WHERE order_id=v.order_id;
 ELSE
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',item_name,'qty',quantity,'price',unit_price,'item_notes',item_notes)
   ORDER BY item_name,quantity,unit_price,item_notes),'[]'::jsonb)
   INTO v_current_items FROM public.ff_order_items WHERE order_id=v.order_id;
 END IF;
 IF v_current_items IS DISTINCT FROM v.old_items THEN RAISE EXCEPTION 'تغيرت الأصناف منذ طلب التعديل؛ يجب إنشاء طلب تعديل جديد'; END IF;
 DELETE FROM public.ff_order_items WHERE order_id=v.order_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      INSERT INTO public.ff_order_items(order_id,item_name,quantity,unit_price,line_total,item_notes)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         SELECT v.order_id,btrim(i.name),i.qty,i.price,i.qty*i.price,coalesce(i.item_notes,'')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             FROM jsonb_to_recordset(v.new_items) AS i(name text,qty numeric,price numeric,item_notes text);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  UPDATE public.ff_orders SET items_total=v.new_total,total=v.new_total+delivery_fee,updated_at=now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WHERE id=v.order_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               UPDATE public.ff49_cashier_receipts SET invoice_ref=coalesce(nullif(btrim(p_invoice_ref),''),invoice_ref),invoiced_by=auth.uid(),invoiced_at=now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       WHERE order_id=v.order_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                UPDATE public.ff50_order_changes SET status='completed',pos_confirmed_by=auth.uid(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           pos_confirmed_at=now(),external_invoice_ref=nullif(btrim(p_invoice_ref),''),completed_at=now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       WHERE id=p_change;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    INSERT INTO public.ff50_order_change_events(change_id,actor_id,old_status,new_status,note)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  VALUES(p_change,auth.uid(),'service_confirmed','completed','إقرار تعديل MicroPOS وتحديث نسخة الطلب');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 RETURN jsonb_build_object('status','completed','order_id',v.order_id,'new_total',v.new_total);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                END; $function$;

CREATE OR REPLACE FUNCTION public.ff50_change_cashier_decide(p_change uuid, p_approve boolean, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                          DECLARE v public.ff50_order_changes%ROWTYPE;v_branch uuid;v_phase text;v_stage text;v_status text;v_new_status text;
                                                          BEGIN
                                                           SELECT * INTO v FROM public.ff50_order_changes WHERE id=p_change FOR UPDATE;
                                                            IF NOT FOUND OR v.status<>'requested' THEN RAISE EXCEPTION 'طلب التعديل غير متاح'; END IF;
                                                             SELECT o.branch_id,t.phase,t.cashier_stage,o.status INTO v_branch,v_phase,v_stage,v_status
                                                              FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id WHERE o.id=v.order_id FOR UPDATE OF o,t;
                                                               IF NOT public.ff49_can_work_branch(v_branch,ARRAY['manager','cashier']) THEN
                                                                 RAISE EXCEPTION 'الموافقة للكاشير المصرح فقط' USING ERRCODE='42501'; END IF;
                                                                  IF NOT public.ff_is_manager() AND NOT ff_private.a05_can_read_order(v.order_id) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 IF v_phase IS DISTINCT FROM 'assigned' OR v_stage='handed_over' OR v_status IN ('cancelled','canceled','delivered','closed','reservation_completed') THEN RAISE EXCEPTION 'فات موعد التعديل قبل التسليم'; END IF;
                                                                   IF p_approve IS NULL THEN RAISE EXCEPTION 'حدد قرار الموافقة أو الرفض' USING ERRCODE='22023'; END IF;
 v_new_status:=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END;
                                                                    UPDATE public.ff50_order_changes SET status=v_new_status,cashier_id=auth.uid(),
                                                                      cashier_decided_at=now(),cashier_note=left(coalesce(p_note,''),500) WHERE id=p_change;
                                                                       INSERT INTO public.ff50_order_change_events(change_id,actor_id,old_status,new_status,note)
                                                                        VALUES(p_change,auth.uid(),v.status,v_new_status,left(coalesce(p_note,''),500));
                                                                         RETURN jsonb_build_object('status',v_new_status,'change_id',p_change);
                                                                         END $function$;

CREATE OR REPLACE FUNCTION public.ff52_late_invoice(p_addition uuid, p_invoice_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
    DECLARE v_branch uuid;v_state text;v_phase text;
    BEGIN
     SELECT o.branch_id,c.state,t.phase INTO v_branch,v_state,v_phase
       FROM public.ff52_late_addition_consent c
          JOIN public.ff38_order_additions a ON a.id=c.addition_id
              JOIN public.ff_orders o ON o.id=a.order_id
                   JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
                         WHERE c.addition_id=p_addition FOR UPDATE OF c,t;
                                IF NOT FOUND OR v_state<>'driver_accepted' OR v_phase NOT IN ('on_way','arrived')
                                        OR NOT public.ff49_can_work_branch(v_branch,ARRAY['manager','cashier'])
                                                 OR length(btrim(coalesce(p_invoice_ref,''))) > 80 THEN
                                                            RAISE EXCEPTION 'موافقة الموصل والكاشير لازمة؛ مرجع الفاتورة اختياري وبحد 80 حرفًا'; END IF;
                                                                        IF NOT public.ff_is_manager() AND NOT ff_private.a05_can_read_order((SELECT a.order_id FROM public.ff38_order_additions a WHERE a.id=p_addition)) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 INSERT INTO public.ff52_addition_pos(addition_id,invoice_ref,recorded_by)
                                                                                     VALUES(p_addition,nullif(btrim(p_invoice_ref),''),auth.uid());
                                                                                                   UPDATE public.ff38_order_additions SET status='invoiced',invoiced_by=auth.uid(),invoiced_at=now()
                                                                                                                  WHERE id=p_addition AND status='pending';
                                                                                                                                  IF NOT FOUND THEN RAISE EXCEPTION 'الإضافة لم تعد معلقة'; END IF;
                                                                                                                                                   UPDATE public.ff52_late_addition_consent SET state='invoiced' WHERE addition_id=p_addition;
                                                                                                                                                                     RETURN jsonb_build_object('invoiced',true);
                                                                                                                                                                                       END; $function$;

CREATE OR REPLACE FUNCTION public.ff70_visible_item_notes()
 RETURNS TABLE(order_id uuid, item_name text, quantity numeric, unit_price numeric, item_notes text, item_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT oi.order_id, oi.item_name::text, oi.quantity::numeric, oi.unit_price::numeric,
         oi.item_notes::text, oi.id
          FROM public.ff_order_items oi
           JOIN public.ff_orders o ON o.id=oi.order_id
            WHERE auth.uid() IS NOT NULL AND oi.item_notes <> ''
 AND (NOT EXISTS(SELECT FROM public.ff_profiles p WHERE p.user_id=auth.uid() AND p.role='cashier') OR ff_private.a05_can_read_order(o.id))
             AND (
                public.ff49_can_work_branch(o.branch_id, ARRAY['manager','customer_service','cashier','assembly']::text[])
                 );
                 $function$;
